/* ==UserStyle==
@name           Universal RGB Text
@namespace      majestic
@version        1.0.0
@author         @Majestic
@description    Clean universal RGB text animation.
==/UserStyle== */

@keyframes rgbText {
    0%   { color: #ff0000; }
    16%  { color: #ff00ff; }
    33%  { color: #0000ff; }
    50%  { color: #00ffff; }
    66%  { color: #00ff00; }
    83%  { color: #ffff00; }
    100% { color: #ff0000; }
}

body,
body * {
    animation: rgbText 8s linear infinite !important;
}

a {
    animation: rgbText 5s linear infinite !important;
}

h1, h2, h3, h4, h5, h6 {
    animation: rgbText 4s linear infinite !important;
}

button,
[role="button"] {
    animation: rgbText 6s linear infinite !important;
}

input,
textarea {
    animation: rgbText 6s linear infinite !important;
}
